const incoming = $input.first().json;
const body = incoming.body;
function result(status, speech, extra = {}) { return [{json:{valid:false,status,reply:{ok:false,speech},...extra}}]; }
if (!body || typeof body !== 'object' || Array.isArray(body)) return result(400,'Envie um objeto JSON válido.');
const allowed = ['get_patient_data','log_meal','log_measurement','request_appointment'];
if (!allowed.includes(body.action)) return result(400,'Ação não reconhecida.');
if (typeof body.patientUid !== 'string' || !body.patientUid.trim() || body.patientUid.length > 128 || body.patientUid.includes('/')) return result(400,'Paciente não identificado. Entre novamente no aplicativo.');
const p = body.payload === undefined ? {} : body.payload;
if (!p || typeof p !== 'object' || Array.isArray(p)) return result(400,'Dados da ação inválidos.');
if (body.action !== 'get_patient_data' && body.confirmed !== true) return result(422,'Confirme os dados com o paciente antes de registrar esta ação.');
const payload = {};
const str = (v, max) => typeof v === 'string' && v.trim().length <= max ? v.trim() : null;
const number = (v) => typeof v === 'number' ? v : typeof v === 'string' && /^[0-9]+(?:[.,][0-9]+)?$/.test(v.trim()) ? Number(v.trim().replace(',','.')) : NaN;
if (body.action === 'log_meal') {
  payload.description = str(p.description, 2000);
  if (!payload.description) return result(422,'O que você comeu nesta refeição?');
  payload.mealTime = p.mealTime === undefined ? '' : str(p.mealTime,80);
  if (payload.mealTime === null) return result(422,'Informe o horário ou o nome da refeição.');
}
if (body.action === 'log_measurement') {
  payload.weight = number(p.weight);
  if (!Number.isFinite(payload.weight) || payload.weight <= 20 || payload.weight > 500) return result(422,'Informe um peso válido em quilogramas.');
  if (p.bodyFat !== undefined && p.bodyFat !== null && p.bodyFat !== '') {
    payload.bodyFat = number(p.bodyFat);
    if (!Number.isFinite(payload.bodyFat) || payload.bodyFat <= 0 || payload.bodyFat >= 100) return result(422,'Informe um percentual de gordura entre zero e cem.');
  }
}
if (body.action === 'request_appointment') {
  payload.preferredDate = str(p.preferredDate,100);
  payload.notes = p.notes === undefined ? '' : str(p.notes,1000);
  if (!payload.preferredDate) return result(422,'Qual data e horário você prefere para a consulta?');
  if (payload.notes === null) return result(422,'Resuma as observações da consulta.');
}
const token = incoming.headers?.['x-patient-token'];
if (typeof token !== 'string' || token.length < 20 || token.length > 8192) return result(401,'Sua sessão precisa ser autenticada novamente no aplicativo.');
return [{json:{valid:true,request:{action:body.action,patientUid:body.patientUid,payload,confirmed:body.confirmed === true},patientToken:token}}];

// Ativar somente após validar a identidade no backend e testar a persistência no app.
const productionReady = false;
const appBaseUrl = '';
const data = $input.first().json;
const validUrl = appBaseUrl.startsWith('https://') && appBaseUrl.length > 8 && !appBaseUrl.includes(' ');
if (!productionReady || !validUrl) {
  return [{json:{...data,valid:false,status:503,reply:{ok:false,speech:'A integração da Ali está em configuração. Nenhum registro foi alterado.'}}}];
}
const base = appBaseUrl.endsWith('/') ? appBaseUrl.slice(0,-1) : appBaseUrl;
return [{json:{...data,apiUrl:base+'/api/agent/action'}}];

const r = $input.first().json;
const body = r.body;
const status = Number(r.statusCode);
if (r.error || !body || typeof body !== 'object' || typeof body.ok !== 'boolean' || typeof body.speech !== 'string') {
 return [{json:{status:502,reply:{ok:false,speech:'Não consegui confirmar o resultado no aplicativo. Confira o registro antes de tentar novamente.'}}}];
}
const ok = status >= 200 && status < 300 && body.ok === true;
return [{json:{status:ok?200:(status>=400&&status<=599?status:422),reply:{ok,speech:body.speech,...(ok && body.patient ? {patient:body.patient}: {}),...(ok && body.approvedPlan ? {approvedPlan:body.approvedPlan}: {})}}}];
